// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PrivatePool} from "../src/PrivatePool.sol";

contract InvMutTest is Test {
    PrivatePool c;
    function setUp() public { c = new PrivatePool(address(this), address(this), address(this)); }

    function testFuzz_property(
        address baseToken,
        address nft,
        uint128 virtBase,
        uint128 virtNft,
        uint56 changeFee,
        uint16 feeRate,
        bytes32 merkleRoot,
        bool useOracle,
        bool payRoy
    ) public {
        // keep the reference's own admissibility domain: fee rate must be <= 5000
        feeRate = uint16(bound(feeRate, 0, 5000));
        // the base token must be nonzero so the mutant's forced zero diverges
        vm.assume(baseToken != address(0));

        c.initialize(baseToken, nft, virtBase, virtNft, changeFee, feeRate, merkleRoot, useOracle, payRoy);

        // GENERAL RULE: whatever base token the pool was initialized with is the
        // token the pool reports as its flash-loan/fee token.
        assertTrue(c.flashFeeToken() == baseToken);
    }
}
